always_comb
  begin
    break_interruptA =  (rsr_qVotedA=='0) & (break_qVotedA|break_dA) & (~ filtered_rxd_qVotedA ) ;
    fifo_clearA = 1'b1;
    trigger_oA = 1'b0;
    tl_charactersA = 4'b0001;
    fifo_pushA = 1'b0;
    fifo_data_iA = '0;
    timeout_count_dA = timeout_count_qVotedA;
    timeout_oA = 1'b0;
    character_lengthA =  (6'd02+word_len_bitsA+reg_read_iA.lcr.par_en+reg_read_iA.lcr.stop_bits) ;
    timeout_levelA =  (character_lengthA<<2)  + 6'd01;
    fifo_error_index_dA = fifo_error_index_qVotedA;
    reg_write_oA = '0;
    state_dA = state_qVotedA;
    rsr_dA = rsr_qVotedA;
    bitcount_dA = bitcount_qVotedA;
    parity_err_dA = parity_err_qVotedA;
    framing_err_dA = framing_err_qVotedA;
