    par_finishA = 1'b0;
    stop_finishA = 1'b0;
    write_initA = 1'b0;
    data_parityA = 1'b0;
    timing_init_clearA = 1'b0;
    timing_loadA = 1'b0;
    timing_offsetA = 5'b00000;
    fifo_clearA = 1'b1;
    fifo_popA = 1'b0;
    rhr_full_dA = rhr_full_qVotedA;
    case (reg_read_iA.lcr.word_len)
      2'b00 : word_len_bitsA = 3'b100;
      2'b01 : word_len_bitsA = 3'b101;
      2'b10 : word_len_bitsA = 3'b110;
      2'b11 : word_len_bitsA = 3'b111;
      default : word_len_bitsA = 3'b111;
    endcase
    if (reg_read_iA.obi_read_rhr)
      begin
        reg_write_oA.rhr = '0;
        reg_write_oA.rhr_valid = 1'b1;
        rhr_full_dA = 1'b0;
        reg_write_oA.data_ready = 1'b0;
        reg_write_oA.dr_valid = 1'b1;
      end

    if (reg_read_iA.obi_read_lsr)
      begin
        reg_write_oA.overrun = 1'b0;
        reg_write_oA.par_err = 1'b0;
        reg_write_oA.frame_err = 1'b0;
        reg_write_oA.break_ind = 1'b0;
        reg_write_oA.overrun_valid = 1'b0;
        reg_write_oA.par_valid = 1'b0;
        reg_write_oA.frame_valid = 1'b0;
        reg_write_oA.break_valid = 1'b0;
        if (fifo_error_index_qVotedA==4'b0000)
          begin
            reg_write_oA.fifo_err = 1'b0;
            reg_write_oA.fifo_err_valid = 1'b1;
          end

      end

    if (state_qVotedA==RXDATA)
      begin
