                  state_dC = RXDATA;
                end
              else
                begin
                  state_dC = RXIDLE;
                end
            end

        end
      RXDATA : 
        begin
          if (rsr_finishC)
            begin
              if (reg_read_iC.lcr.par_en)
                begin
                  state_dC = RXPAR;
                end
              else
                begin
                  state_dC = RXSTOP;
                end
            end

        end
      RXPAR : 
        begin
          if (par_finishC)
            begin
              state_dC = RXSTOP;
            end

        end
      RXSTOP : 
        begin
          if (stop_finishC)
            begin
              if (framing_err_qVotedC)
                begin
                  state_dC = RXRESYNCHRONIZE;
                end
              else
                begin
                  state_dC = RXIDLE;
                end
            end

        end
      RXRESYNCHRONIZE : 
        begin
          if (filtered_rxd_qVotedC&~sync_rxdC)
            begin
              state_dC = RXSTART;
            end
          else
            begin
              state_dC = RXIDLE;
            end
        end
      default : state_dC = RXIDLE;
    endcase
    if (reg_read_iC.fcr.fifo_en)
      begin
        reg_write_oC.dr_valid = 1'b1;
        reg_write_oC.data_ready = write_initC|~fifo_emptyC|rhr_full_qVotedC;
        if ((~ rhr_full_qVotedC )&(~ fifo_emptyC ))
          begin
            reg_write_oC.rhr = fifo_data_oC[7:0];
            reg_write_oC.rhr_valid = 1'b1;
            reg_write_oC.data_ready = 1'b1;
            rhr_full_dC = 1'b1;
            reg_write_oC.break_ind = fifo_data_oC[8];
            reg_write_oC.frame_err = fifo_data_oC[9];
            reg_write_oC.par_err = fifo_data_oC[10];
            reg_write_oC.break_valid = 1'b1;
            reg_write_oC.frame_valid = 1'b1;
            reg_write_oC.par_valid = 1'b1;
            fifo_popC = 1'b1;
            if (4'b0000!=fifo_error_index_qVotedC)
              begin
                fifo_error_index_dC = fifo_error_index_qVotedC - 'b0001;
              end

          end

      end
    else
      begin
        if (write_initC)
          begin
            if (rhr_full_qVotedC)
              begin
                reg_write_oC.overrun = 1'b1;
                reg_write_oC.overrun_valid = 1'b1;
              end

            reg_write_oC.rhr = rsr_qVotedC;
            reg_write_oC.rhr_valid = 1'b1;
            rhr_full_dC = 1'b1;
            reg_write_oC.data_ready = 1'b1;
            reg_write_oC.dr_valid = 1'b1;
            reg_write_oC.par_err = parity_err_qVotedC;
            reg_write_oC.frame_err = framing_err_qVotedC;
            reg_write_oC.break_ind = break_interruptC;
            reg_write_oC.break_ind = 1'b1;
            reg_write_oC.break_valid = 1'b1;
            reg_write_oC.par_valid = 1'b1;
            reg_write_oC.frame_valid = 1'b1;
          end

      end
    if (reg_read_iC.fcr.fifo_en)
      begin
        fifo_clearC = 1'b0;
        if (reg_read_iC.fcr.rx_fifo_rst)
          begin
            fifo_clearC = 1'b1;
            reg_write_oC.fifo_rst = 1'b0;
            reg_write_oC.fifo_rst_valid = 1'b1;
          end

        case (reg_read_iC.fcr.rx_fifo_tl)
          2'b00 : tl_charactersC = 4'b0001;
          2'b01 : tl_charactersC = 4'b0100;
          2'b10 : tl_charactersC = 4'b1000;
          2'b11 : tl_charactersC = 4'b1110;
          default : tl_charactersC = 4'b0001;
        endcase
        if (tl_charactersC<=fifo_usageC)
          begin
            trigger_oC = 1'b1;
          end

        if (write_initC)
          begin
            if (fifo_fullC)
              begin
                reg_write_oC.overrun = 1'b1;
                reg_write_oC.overrun_valid = 1'b1;
              end
            else
              begin
                fifo_pushC = 1'b1;
                fifo_data_iC = {parity_err_qVotedC, framing_err_qVotedC, break_interruptC, rsr_qVotedC};
                if (parity_err_qVotedC|framing_err_qVotedC|break_interruptC)
                  begin
                    fifo_error_index_dC = fifo_usageC;
                    reg_write_oC.fifo_err = 1'b1;
                    reg_write_oC.fifo_err_valid = 1'b1;
                  end

              end
          end

        if (reg_read_iC.obi_read_rhr|write_initC)
          begin
            timeout_count_dC = '0;
          end
        else
          if (~fifo_emptyC|rhr_full_qVotedC)
            begin
              if (baud_rate_edge_iC)
                begin
                  timeout_count_dC = timeout_count_qVotedC + 1;
                end

              if (timeout_count_qVotedC==timeout_levelC)
                begin
                  timeout_oC = 1'b1;
                  timeout_count_dC = timeout_count_qVotedC;
                end

            end

      end

  end

